import{matchesSourceRow}from'./source-row-variants.mjs';
import{GYM12}from'./registration.mjs';import{gym12VisualState,gym12Actors}from'./visual-state.mjs';
const authorities=new WeakMap,grants=new WeakMap;
const record=(o,keys)=>{if(!o||Object.getPrototypeOf(o)!==Object.prototype||Reflect.ownKeys(o).length!==keys.length)return null;const r={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return null;r[k]=d.value}return r};
const find=id=>Object.values(GYM12).flatMap(g=>g.points.map(r=>({g,r}))).find(x=>x.r.pointId===id);
export function isGym12Request(id,a){const x=find(id),v=record(a,['type']);return !!x&&v?.type===x.r.kind}
export function createGym12Authority({getWorld,readNative,getSignal}={}){if([getWorld,readNative,getSignal].some(f=>typeof f!=='function'))throw Error('LIVE_GYM12_OWNER_REQUIRED');const a=Object.freeze({});authorities.set(a,{getWorld,readNative,getSignal});return a}
export const isGym12Authority=a=>authorities.has(a);
export function gym12Facing(r,foot,anchor=r.anchor){if(r.facing)return r.facing;const dx=anchor[0]-foot[0],dy=anchor[1]-foot[1];return Math.abs(dy)>=Math.abs(dx)?dy>=0?'down':'up':dx>=0?'right':'left'}
function canonical(w,g,r){const s=w.snapshot(),p=w.definition.points[r.pointId];return s.position.scene===g.mapId&&s.world.mapId===g.mapId&&matchesSourceRow(w.adapter,r.pointId,p)&&(r.kind!=='trainer'||w.story.trainerAvailable(p.trainerId)||(!w.story.contract.trainers[p.trainerId]?.repeatable&&s.progress.defeatedTrainers.includes(p.trainerId)))}
function read(o,g,r,w){const n=record(o.readNative(),['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','phase','sessionEpoch','gameplayRevision','state']);if(!n||n.version!==1||n.phase!=='field'||n.sceneId!==g.sceneId||n.mapId!==g.mapId||n.revision!==g.revision||n.gameplayRevision!==g.gameplayRevision||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<1||n.state!==gym12VisualState(w.snapshot(),g.gymNo)||!g.states[n.state]||n.imageSHA!==g.image.sha256||n.maskSHA!==g.states[n.state].maskSHA)return null;const f=n.foot;if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3||f.length!==2)return null;for(const i of ['0','1']){const d=Object.getOwnPropertyDescriptor(f,i);if(!d?.enumerable||!Object.hasOwn(d,'value')||!Number.isSafeInteger(d.value))return null}const anchor=r.kind==='trainer'?gym12Actors(g.gymNo,n.state).find(a=>a.id===r.sourceRow.trainerId).foot:r.anchor;if(!r.approachRows[n.state]?.some(([y,a,b])=>f[1]===y&&f[0]>=a&&f[0]<b)||Math.abs(f[0]-anchor[0])+Math.abs(f[1]-anchor[1])>r.readL1||n.facing!==gym12Facing(r,f,anchor))return null;return{epoch:n.sessionEpoch,foot:[...f],facing:n.facing,state:n.state}}
export function mintGym12Grant(a,w,id){const o=authorities.get(a),x=find(id);if(!o||o.getWorld()!==w||!x||!canonical(w,x.g,x.r))throw Error('GYM12_UNAVAILABLE');const n=read(o,x.g,x.r,w),signal=o.getSignal();if(!n)throw Error('GYM12_APPROACH_REQUIRED');if(!(signal instanceof AbortSignal)||signal.aborted)throw Error('GYM12_LIFECYCLE_REQUIRED');const grant=Object.freeze({});grants.set(grant,{a,w,...x,n,signal});return grant}
export function validateGym12Grant(grant,w,pointId){const q=grants.get(grant),o=q&&authorities.get(q.a);if(!q||q.w!==w||!o||o.getWorld()!==w||q.signal.aborted||o.getSignal()!==q.signal||pointId!==undefined&&q.r.pointId!==pointId||!canonical(w,q.g,q.r))return false;const n=read(o,q.g,q.r,w);return !!n&&JSON.stringify(n)===JSON.stringify(q.n)}
export function assertGym12Grant(g,w){if(!validateGym12Grant(g,w))throw Error('GYM12_OWNER_DRIFT')}
export function revokeGym12Grant(g){grants.delete(g)}
export function signalGym12Grant(g,w){assertGym12Grant(g,w);return grants.get(g).signal}
